class Query{constructor(sql,args=[]){this.sql=sql;this.args=args;}bind(...args){return new Query(this.sql,args);}runSync(){const r=db.prepare(this.sql).run(...this.args);return {success:true,meta:{changes:Number(r.changes)}};}async run(){return this.runSync();}async first(){return db.prepare(this.sql).get(...this.args)||null;}async all(){return {results:db.prepare(this.sql).all(...this.args),success:true};}}
globalThis.__hubTestEnv={OPENAI_API_KEY:'test-key-not-a-credential',OPENAI_MODEL:'gpt-5.4-mini',SITES_SERVICE_TOKEN:'test-service-not-a-credential',DB:{prepare:s=>new Query(s),batch:async list=>{db.exec('BEGIN');try{const r=list.map(q=>q.runSync());db.exec('COMMIT');return r;}catch(e){db.exec('ROLLBACK');throw e;}}}};
