const request=(path,data,headers={})=>new Request('https://test.example/api/'+path,{method:data?'POST':'GET',headers:{...(data?{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()}:{}),...headers},body:data?JSON.stringify(data):undefined});
const ownerHeaders={'oai-authenticated-user-id':'test-owner'};
function participantMock({failClaude=false,wait=null}={}){const original=globalThis.fetch,stats={claude:0,grok:0};globalThis.__hubTestEnv.ANTHROPIC_API_KEY='test-anthropic-not-a-credential';globalThis.__hubTestEnv.XAI_API_KEY='test-xai-not-a-credential';globalThis.fetch=async(url,init)=>{if(url==='https://api.anthropic.com/v1/messages'||url==='https://api.x.ai/v1/responses'){const claude=url.includes('anthropic'),input=JSON.parse(init.body);stats[claude?'claude':'grok']++;assert.equal(input.tools,undefined);assert.match(claude?input.messages[0].content:input.input,/실제 외부 실행 없이 통신 테스트|new round/);if(claude){assert.equal(init.headers['x-api-key'],'test-anthropic-not-a-credential');assert.equal(input.model,'claude-sonnet-5-5');}else{assert.equal(init.headers.Authorization,'Bearer test-xai-not-a-credential');assert.equal(input.model,'grok-4.7');assert.equal(input.store,false);}if(wait)await wait;if(claude&&failClaude)return Response.json({error:{message:'limit reached test-anthropic-not-a-credential'}},{status:429});return Response.json(claude?{id:'claude-response',stop_reason:'end_turn',content:[{type:'text',text:'[CLAUDE ACTUAL API] 근거와 실행 순서를 검토했습니다.'}]}:{id:'grok-response',status:'completed',output:[{content:[{type:'output_text',text:'[GROK ACTUAL API] 대안과 위험을 검토했습니다.'}]}]});}return original(url,init);};return stats;}
const config=pid=>actions.connectMuse('test-owner',pid,'https://test.example');
const start=(key=crypto.randomUUID())=>actions.startRoom('test-owner','sandbox','실제 외부 실행 없이 통신 테스트',key);
function voiceUpload(id=crypto.randomUUID(),{project='sandbox',mime='audio/webm',content='fake-audio-bytes',headers=ownerHeaders}={}){const form=new FormData();form.set('audio',new Blob([content],{type:mime}),'recording.webm');return new Request('https://test.example/api/hub/voice-topic?project='+project,{method:'POST',headers:{...headers,'Idempotency-Key':id},body:form});}
function voiceMock({transcript='다음 주 신제품 홍보 영상을 기획해줘. 예산과 타깃을 비교하고 회의를 시작해줘.',audioHold=null,titleFailure=false}={}){const original=globalThis.fetch,stats={speech:0,titles:0};globalThis.fetch=async(url,init)=>{
 if(String(url).endsWith('/audio/transcriptions')){stats.speech++;assert.equal(init.body.get('model'),'gpt-4o-mini-transcribe');assert.equal(init.body.get('language'),'ko');assert.equal(init.body.get('file').type,'audio/webm');if(audioHold)await audioHold;return Response.json({text:transcript});}
 if(String(url).endsWith('/responses')&&JSON.parse(init.body).text?.format?.name==='voice_topic_title'){stats.titles++;const input=JSON.parse(init.body);assert.equal(input.input,transcript.trim());assert.equal(input.store,false);assert.equal(input.tools,undefined);return titleFailure?Response.json({error:{}},{status:429}):Response.json({status:'completed',output:[{content:[{type:'output_text',text:JSON.stringify({title:'신제품 홍보 영상 기획'})}]}]});}
 return original(url,init);
 };return stats;}
async function claim(c){const r=await route.POST(request('muse/pull',{projectId:c.project},c.headers));assert.equal(r.status,200);return r.json();}
async function reply(c,d,key='reply-once'){return route.POST(request('muse/reply',{deliveryId:d.delivery.id,leaseId:d.delivery.lease_id,reply:'[TEST ADAPTER] 실제 Muse가 아닌 HTTP 검증 응답'}, {...c.headers,'Idempotency-Key':key}));}

test('owner UI rejects anonymous and agent-only requests',async()=>{const c=await config('sandbox');assert.equal((await route.GET(request('hub?project=sandbox'))).status,401);assert.equal((await route.GET(request('hub?project=sandbox',null,c.headers))).status,401);});
test('cancelled schema initialization cannot strand another Worker request',async()=>{const isolated=await import(new URL('hub-core.mjs?schema-request-isolation',out)),original=globalThis.__hubTestEnv.DB.batch;let rejectFirst,resolveSecond,attempts=0;globalThis.__hubTestEnv.DB.batch=async()=>{attempts++;return new Promise((resolve,reject)=>{if(attempts===1)rejectFirst=reject;else resolveSecond=resolve;});};try{const first=isolated.ensureStudioSchema();const rejected=assert.rejects(first,/cancelled/);const second=isolated.ensureStudioSchema();assert.equal(attempts,2);resolveSecond([]);await second;rejectFirst(Error('cancelled'));await rejected;await isolated.ensureStudioSchema();assert.equal(attempts,2);}finally{globalThis.__hubTestEnv.DB.batch=original;}});
test('start calls model once and preserves idempotency',async()=>{const a=await start('start-once'),b=await start('start-once');assert.equal(a.roomId,b.roomId);assert.equal(calls,1);assert.equal(db.prepare('SELECT COUNT(*) n FROM hub_messages').get().n,2);assert.equal((await core.state('sandbox')).rooms[0].status,'waiting_muse');});
test('voice creates GPT title and starts a meeting with full unabridged instruction exactly once',async()=>{const transcript='신제품 홍보 기획. '+ '세부 요청을 빠짐없이 반영해주세요. '.repeat(45),stats=voiceMock({transcript}),id=crypto.randomUUID();const prepared=await route.POST(voiceUpload(id));assert.equal(prepared.status,200);const command=await prepared.json();assert.equal(command.status,'ready');assert.equal(command.title,'신제품 홍보 영상 기획');assert.equal(db.prepare('SELECT COUNT(*) n FROM hub_rooms').get().n,0);const run=()=>route.POST(request('hub/voice-topic/start',{projectId:'sandbox',commandId:id},ownerHeaders));const [one,two]=await Promise.all([run(),run()]);assert.equal(one.status,200);assert.equal(two.status,200);const a=await one.json(),b=await two.json();assert.equal(a.roomId,b.roomId);assert.equal(db.prepare("SELECT body FROM hub_messages WHERE sender='chief'").get().body,transcript.trim());assert.equal(db.prepare('SELECT title FROM hub_rooms').get().title,command.title);assert.equal(db.prepare('SELECT COUNT(*) n FROM hub_rooms').get().n,1);assert.equal(db.prepare('SELECT COUNT(*) n FROM hub_production_jobs').get().n,0);assert.equal(calls,1);assert.deepEqual(stats,{speech:1,titles:1});const replay=await (await route.POST(voiceUpload(id))).json();assert.equal(replay.roomId,a.roomId);assert.deepEqual(stats,{speech:1,titles:1});});
test('voice concurrent upload and status polling never transcribe twice',async()=>{let release;const held=new Promise(r=>release=r),stats=voiceMock({audioHold:held}),id=crypto.randomUUID(),first=route.POST(voiceUpload(id));while(!stats.speech)await new Promise(r=>setTimeout(r,1));const duplicate=await route.POST(voiceUpload(id));assert.equal((await duplicate.json()).status,'processing');const status=await route.GET(request('hub/voice-topic?project=sandbox&id='+id,null,ownerHeaders));assert.equal((await status.json()).status,'processing');release();assert.equal((await (await first).json()).status,'ready');assert.deepEqual(stats,{speech:1,titles:1});});
test('voice requires owner, same origin, valid project/audio, and matching retry payload',async()=>{const stats=voiceMock(),id=crypto.randomUUID();assert.equal((await route.POST(voiceUpload(id,{headers:{}}))).status,401);assert.equal((await route.POST(voiceUpload(id,{headers:{...ownerHeaders,Origin:'https://untrusted.example'}}))).status,403);assert.equal((await route.POST(voiceUpload(id,{project:'missing'}))).status,400);assert.equal((await route.POST(voiceUpload(id,{mime:'text/plain'}))).status,400);assert.equal((await route.POST(voiceUpload(id,{content:''}))).status,400);assert.deepEqual(stats,{speech:0,titles:0});await route.POST(voiceUpload(id));assert.equal((await route.POST(voiceUpload(id,{content:'different-audio'}))).status,409);assert.equal((await route.GET(request('hub/voice-topic?project=sandbox&id='+id,null,{'oai-authenticated-user-id':'another-owner'}))).status,404);assert.equal((await route.POST(request('hub/voice-topic/start',{projectId:'sandbox',commandId:id},{'oai-authenticated-user-id':'another-owner'}))).status,404);});
test('empty speech or title API failure does not create a meeting or repeat charges on replay',async()=>{let stats=voiceMock({transcript:'  '}),id=crypto.randomUUID();assert.equal((await (await route.POST(voiceUpload(id))).json()).status,'failed');assert.deepEqual(stats,{speech:1,titles:0});assert.equal((await route.POST(request('hub/voice-topic/start',{projectId:'sandbox',commandId:id},ownerHeaders))).status,409);stats=voiceMock({titleFailure:true});id=crypto.randomUUID();const result=await (await route.POST(voiceUpload(id))).json();assert.equal(result.status,'failed');assert.match(result.error,/한도/);await route.POST(voiceUpload(id));assert.deepEqual(stats,{speech:1,titles:1});assert.equal(db.prepare('SELECT COUNT(*) n FROM hub_rooms').get().n,0);});
test('voice Director failure leaves the instruction and recoverable meeting without duplicate rooms',async()=>{voiceMock();mode='quota';const id=crypto.randomUUID();await route.POST(voiceUpload(id));const input={projectId:'sandbox',commandId:id};const first=await (await route.POST(request('hub/voice-topic/start',input,ownerHeaders))).json();assert.equal(first.status,'done');assert.ok(first.roomId);assert.equal((await (await route.POST(request('hub/voice-topic/start',input,ownerHeaders))).json()).roomId,first.roomId);assert.equal(calls,1);assert.equal(db.prepare('SELECT COUNT(*) n FROM hub_rooms').get().n,1);});
test('creating a named meeting stays silent until Chief sends the first instruction',async()=>{const c=await config('sandbox'),payload={projectId:'sandbox',title:'서비스 소개 제작 회의'},headers={...ownerHeaders,'Idempotency-Key':'named-meeting'};const made=await route.POST(request('hub/room/create',payload,headers)),room=await made.json();assert.equal(made.status,200);assert.equal(room.status,'ready');assert.equal(calls,0);assert.equal(db.prepare('SELECT COUNT(*) n FROM hub_messages WHERE room_id=?').get(room.roomId).n,0);assert.equal((await claim(c)).delivery,null);const sent=await route.POST(request('hub/message',{projectId:'sandbox',roomId:room.roomId,message:'모든 에이전트는 서비스 소개 이미지를 논의해줘'},ownerHeaders));assert.equal(sent.status,200);assert.equal(calls,1);assert.equal(db.prepare("SELECT COUNT(*) n FROM hub_messages WHERE room_id=? AND sender='chief'").get(room.roomId).n,1);assert.equal(db.prepare("SELECT COUNT(*) n FROM hub_messages WHERE room_id=? AND sender='director'").get(room.roomId).n,1);assert.ok((await claim(c)).delivery);});
test('Muse HTTP reply automatically invokes Director without UI or timer',async()=>{const c=await config('sandbox');await start();const d=await claim(c);assert.ok(d.delivery.lease_id);const r=await reply(c,d);assert.equal(r.status,200);assert.equal(calls,2);assert.equal(db.prepare("SELECT COUNT(*) n FROM hub_messages WHERE sender='director'").get().n,2);assert.equal(db.prepare('SELECT status FROM hub_deliveries WHERE id=?').get(d.delivery.id).status,'acked');});
test('three-agent round creates one report with independently approved action items',async()=>{const c=await config('sandbox'),room=await start('meeting-report'),d=await claim(c);db.prepare("INSERT INTO hub_messages(id,room_id,project,sender,body,created_at) VALUES('round-gemini',?,'sandbox','gemini','재미니의 실제 의견',?)").run(room.roomId,new Date().toISOString());mode='report';const answered=await reply(c,d,'meeting-report-reply');assert.equal(answered.status,200);let state=await core.state('sandbox',room.roomId);assert.equal(state.rooms.find(r=>r.id===room.roomId).status,'awaiting_approval');assert.equal(state.reports.length,1);assert.equal(state.reports[0].actions.length,2);const [first,second]=state.reports[0].actions;assert.equal((await route.POST(request('hub/action/approve',{projectId:'sandbox',id:first.id}))).status,401);assert.equal((await route.POST(request('hub/action/approve',{projectId:'sandbox',id:first.id},ownerHeaders))).status,200);assert.equal((await route.POST(request('hub/action/reject',{projectId:'sandbox',id:second.id},ownerHeaders))).status,200);state=await core.state('sandbox',room.roomId);assert.deepEqual(state.reports[0].actions.map(a=>a.status),['approved','rejected']);assert.equal(state.reports[0].status,'approved');assert.equal(state.rooms.find(r=>r.id===room.roomId).status,'ready');assert.ok(db.prepare("SELECT id FROM hub_audit WHERE action='action.approved'").get());assert.ok(db.prepare("SELECT id FROM hub_audit WHERE action='action.rejected'").get());});
test('duplicate Muse reply does not charge another model call',async()=>{const c=await config('sandbox');await start();const d=await claim(c);assert.equal((await reply(c,d)).status,200);assert.equal((await reply(c,d)).status,200);assert.equal(calls,2);});
