test('production requires Chief approval before one Studio claim and records result',async()=>{
 const room=await start('production-room'),studio=await actions.connectStudio('test-owner','sandbox','https://test.example');
 const proposal={projectId:'sandbox',roomId:room.roomId,title:'빈티지 포스터',mode:'text-image',prompt:'1980년대 미국 빈티지 컬러의 스튜디오 포스터',aspect:'16:9',resolution:'1536x864'};
 const created=await route.POST(request('hub/production/create',proposal,{...ownerHeaders,'Idempotency-Key':'production-once'}));assert.equal(created.status,200);const made=await created.json();
 const empty=await route.POST(request('studio/pull',{projectId:'sandbox'},studio.headers));assert.equal((await empty.json()).job,null);
 assert.equal((await route.POST(request('hub/production/approve',{projectId:'sandbox',id:made.jobId},ownerHeaders))).status,200);
 const claims=await Promise.all([route.POST(request('studio/pull',{projectId:'sandbox'},studio.headers)),route.POST(request('studio/pull',{projectId:'sandbox'},studio.headers))]);
 const payloads=await Promise.all(claims.map(r=>r.json())),claimed=payloads.find(x=>x.job)?.job;assert.ok(claimed);assert.equal(payloads.filter(x=>x.job).length,1);assert.equal(claimed.prompt,proposal.prompt);
 assert.equal((await route.POST(request('studio/result',{projectId:'sandbox',jobId:claimed.id,leaseId:claimed.lease_id,status:'running',studioJobId:'local-123'},studio.headers))).status,200);
 assert.equal((await route.POST(request('studio/result',{projectId:'sandbox',jobId:claimed.id,leaseId:claimed.lease_id,status:'complete',studioJobId:'local-123',result:{assets:['output.png']}},studio.headers))).status,200);
 const state=await core.state('sandbox',room.roomId);assert.equal(state.productions[0].status,'complete');assert.deepEqual(state.productions[0].result.assets,['output.png']);assert.equal(state.externalActionsEnabled,true);
});
