 const room=await start('production-reject'),made=await actions.createProduction('test-owner','sandbox',{roomId:room.roomId,title:'반려안',mode:'text-video',prompt:'실행하지 않을 영상'},'reject-once'),studio=await actions.connectStudio('test-owner','sandbox','https://test.example');
