test('Web push encrypts one real protocol payload, never returns private keys and rejects arbitrary endpoints',async()=>{
 const n=await import(new URL('notifications.mjs',out));await assert.rejects(n.noticeSubscribe('test-owner',{endpoint:'https://127.0.0.1/admin',keys:{p256dh:'a'.repeat(87),auth:'a'.repeat(22)}}),/브라우저/);
 const pair=await crypto.subtle.generateKey({name:'ECDH',namedCurve:'P-256'},true,['deriveBits']);const b64=x=>Buffer.from(x).toString('base64url');
 const subscription={endpoint:'https://fcm.googleapis.com/fcm/send/test-device',keys:{p256dh:b64(await crypto.subtle.exportKey('raw',pair.publicKey)),auth:b64(crypto.getRandomValues(new Uint8Array(16)))}};
 await n.noticeSubscribe('test-owner',subscription);const key=await n.noticeKey();assert.ok(key.publicKey);assert.equal(key.privateKey,undefined);
 const room=await actions.createRoom('test-owner','sandbox','푸시 확인','push-room');await actions.createProduction('test-owner','sandbox',{roomId:room.roomId,title:'실제 규격 암호화',mode:'text-image',prompt:'poster'},'push-job');
 let sends=0;globalThis.fetch=async(url,request)=>{assert.equal(url,subscription.endpoint);sends++;assert.equal(new Headers(request.headers).get('content-encoding'),'aes128gcm');assert.doesNotMatch(Buffer.from(request.body).toString('utf8'),/실제 규격 암호화/);return new Response(null,{status:201});};
 await n.noticeScan();assert.equal(sends,1);await n.noticeScan();assert.equal(sends,1);
});


